#include "stdafx.h"#include "Server.h"#include <rsuNoNames.h>#include <rsuMemoryManager.h>#include <ConnectHCD.h>#pragma comment( lib, "ConnectHCD.lib")#ifdef _MANAGED#pragma managed(push, off)#endifHINSTANCE g_hInst = 0;static KRsuMemoryManager s_memory;static KNoName s_sharedVars, s_ioVars;static BYTE* _ObjsMemAllocator( size_t size ){  BYTE* p = s_memory.AllocMemory( (DWORD)size );  ASSD( p );  if( !p )  {    p = new BYTE[size];    ZeroMemory( p, size );  }  return p;}static CBase* CreateSharedObj( LPCSTR pszName, DWORD TypeID, int CS ){  CBase *pObj = s_sharedVars.CreateStruct( pszName, TypeID, CS );  return pObj;}static KNoName* GetSharedObjAllocator(){  return &s_sharedVars;};static CBase* IoCreateObj( LPCSTR pszName, DWORD TypeID, int CS ){  CBase *pObj = s_ioVars.CreateStruct( pszName, TypeID, CS );  return pObj;}BOOL APIENTRY DllMain( HMODULE hModule,                       DWORD  ul_reason_for_call,                       LPVOID lpReserved					 ){  switch (ul_reason_for_call)  {  case DLL_PROCESS_ATTACH:    {      g_hInst = hModule;      size_t ms = s_memory.Create( "HCD_Mem", 80 );      s_sharedVars = KNoName::Create( "HcdShared", true, 70000, 7000000, 3000000 );      s_sharedVars.Reset();      s_ioVars = KNoName::Create( "HcdIO", true, 30000, 300000, 3000000 );      s_ioVars.Reset();      KMemoryServiceHCD::Instance().InitMemAllocator( _ObjsMemAllocator );      KMemoryServiceHCD::Instance().InitStructAllocator( CreateSharedObj );      KMemoryServiceHCD::Instance().InitStructGetter( GetSharedObjAllocator );      KMemoryServiceHCD::Instance().InitIoAllocator( IoCreateObj );            if( !pRegisterHCDstructs )        LoadLibrary("HCDRegisterInRSU.dll");      if( pRegisterHCDstructs )        pRegisterHCDstructs();    }    break;  case DLL_THREAD_ATTACH:  case DLL_THREAD_DETACH:  case DLL_PROCESS_DETACH:    break;  }  return TRUE;}#ifdef _MANAGED#pragma managed(pop)#endifextern "C" __declspec(dllexport) IRsuModel* CreateServer(LPCSTR ObjName ){  IRsuModel *pModel = new KServer( ObjName );  return pModel;}